<?php defined( 'ABSPATH' ) || exit; ?>
<header class="dxbus-view__head"><p class="dxbus-eyebrow">Through my lens</p><h2>Route gallery</h2><p>Photographs from the personal archive. Captions and dates reflect when each image was taken.</p></header><label class="dxbus-sr" for="dxb-photo-search">Search photographs</label><input id="dxb-photo-search" type="search" placeholder="Search photos, places, vehicles…"><div class="dxbus-gallery-grid dxb-gallery" id="dxb-gallery"><?php foreach ( $context['photos'] as $photo ) : ?><a class="dxbus-photo-card" href="<?php echo esc_url( $photo['full'] ); ?>" data-photo="<?php echo (int) $photo['index']; ?>" data-photo-route="<?php echo esc_attr( $photo['route'] ); ?>" data-photo-search="<?php echo esc_attr( strtolower( implode( ' ', array_intersect_key( $photo, array_flip( array( 'title', 'route', 'caption', 'operator', 'vehicle', 'location' ) ) ) ) ) ); ?>"><?php echo dxb_dashboard_image( $photo ); ?><div><h3><?php echo esc_html( $photo['title'] ); ?></h3><p><?php echo esc_html( $photo['caption'] ); ?></p><?php if ( $photo['date'] ) : ?><time><?php echo esc_html( $photo['date'] ); ?></time><?php endif; ?></div></a><?php endforeach; ?></div><p id="dxb-gallery-empty" class="dxbus-empty"<?php echo $context['photos'] ? ' hidden' : ''; ?>>No photographs match this route or search. More photographs will appear as the archive grows.</p>
